    Dictionary net_status() {
        Dictionary out;
        out["started"] = started_;
        out["server"] = is_server_;
        out["client_id"] = local_client_id();
        out["tick_rate"] = tick_rate();
        out["send_budget_per_second"] = send_budget();
        out["send_budget_per_tick"] = static_cast<int64_t>(send_bytes_per_tick());
        out["buffer_frames"] = static_cast<int64_t>(buffered_frames_);
        out["bytes_out_per_second"] = sent_per_second_;
        out["bytes_in_per_second"] = received_per_second_;
        if (client_ != nullptr) {
            out["ready"] = client_->connection_state()
                == ashiato::sync::ReplicationClientConnectionState::Ready;
        } else {
            out["ready"] = server_ != nullptr;
        }
        if (server_ != nullptr) {
            out["clients"] = static_cast<int64_t>(server_->client_count());
        }
        return out;
    }

    Dictionary timing() const {
        Dictionary out;
        if (client_ == nullptr) {
            return out;
        }
        const auto& stats = client_->timing_stats();
        out["latency_frames"] = stats.latency_frames;
        out["jitter_frames"] = stats.jitter_frames;
        out["buffer_frames"] = static_cast<int64_t>(stats.current_buffered_frame_lag);
        out["buffer_target"] = static_cast<int64_t>(stats.target_buffered_frame_lag);
        out["prediction_lead"] = static_cast<int64_t>(stats.current_prediction_lead_frames);
        out["packets_received"] = static_cast<int64_t>(stats.server_update_packets_received);
        out["packets_missing"] = static_cast<int64_t>(stats.server_update_packets_missing);
        InputPacketCounters::describe(*client_, out);
        // WHERE THE BUFFERED CLOCK IS, which is what every interpolated craft is drawn at: the registry is applied one
        // integer buffered frame at a time, so a tick on which this moves by 0 or 2 is a tick on which the whole sky
        // holds or leaps together, whatever the budget.
        out["buffered_frame"] = static_cast<int64_t>(client_->buffered_frame());
        out["continuous_buffered_frame"] = client_->continuous_buffered_frame();
        out["estimated_server_frame"] = client_->estimated_server_frame();
        out["last_applied_buffered_frame"] = client_->has_applied_buffered_frame()
            ? static_cast<int64_t>(client_->last_applied_buffered_frame())
            : static_cast<int64_t>(-1);
        return out;
    }

    /// What prediction has cost since the session started.
    ///
    /// `ticks` is the one that matters for a hitch: a rollback replays every frame from
    /// the correction to now, inside the frame that received it. Ten rollbacks of two
    /// ticks is a different machine from two rollbacks of ten.
    /// THE WIRE ROUNDING CHANGES NO BIT A CLIENT RECEIVES.
    ///
    /// Every component whose quantize goes through the wire (`quantize_through_the_wire`) is written twice, once from
    /// the registry's own value and once from what quantize made of it, and the two bit strings are compared. A
    /// client decodes those bits, so equal bits are equal values on every machine. `differ` is the count that must
    /// stay zero; `checked` is how many were compared, so a check that compared nothing cannot pass.
    Dictionary wire_rounding_check() {
        std::int64_t checked = 0;
        std::int64_t differ = 0;
        Dictionary by_component;
        String example;
        const auto hex = [](const ashiato::BitBuffer& bits) {
            String text = String::num_int64(static_cast<int64_t>(bits.bit_size())) + ":";
            for (const std::uint8_t byte : bits.bytes()) {
                text += String::num_int64(byte, 16).lpad(2, "0");
            }
            return text;
        };
        const auto compare = [&](const char* name, const auto& value) {
            using T = std::decay_t<decltype(value)>;
            ashiato::BitBuffer straight;
            ashiato::BitBuffer rounded;
            ashiato::ComponentSerializationContext context{};
            ashiato::sync::SyncComponentTraits<T>::serialize(nullptr, value, straight, context);
            T quantized{};
            ashiato::sync::SyncComponentTraits<T>::quantize(value, quantized);
            ashiato::sync::SyncComponentTraits<T>::serialize(nullptr, quantized, rounded, context);
            ++checked;
            if (straight.bit_size() != rounded.bit_size() || straight.bytes() != rounded.bytes()) {
                ++differ;
                by_component[name] = static_cast<int64_t>(by_component.get(name, 0)) + 1;
                if (example.is_empty()) {
                    example = String(name) + " straight " + hex(straight) + " rounded " + hex(rounded);
                }
            }
        };
        registry_.view<const cockpit::VehicleState>().each(
            [&](ashiato::Entity, const cockpit::VehicleState& value) { compare("VehicleState", value); });
        registry_.view<const cockpit::CraftControls>().each(
            [&](ashiato::Entity, const cockpit::CraftControls& value) { compare("CraftControls", value); });
        registry_.view<const cockpit::CraftSystems>().each(
            [&](ashiato::Entity, const cockpit::CraftSystems& value) { compare("CraftSystems", value); });
        registry_.view<const cockpit::CabinSystems>().each(
            [&](ashiato::Entity, const cockpit::CabinSystems& value) { compare("CabinSystems", value); });
        registry_.view<const cockpit::RailCar>().each(
            [&](ashiato::Entity, const cockpit::RailCar& value) { compare("RailCar", value); });
        Dictionary out;
        out["checked"] = checked;
        out["differ"] = differ;
        out["by_component"] = by_component;
        out["example"] = example;
        return out;
    }

    /// Exact ControlInput codec sizes plus the cost of encoding one worst-case
    /// eight-frame packet. Kept as a diagnostic beside wire_rounding_check so a
    /// future field addition cannot leave the bandwidth numbers in the docs stale.
    Dictionary input_wire_probe(int64_t iterations = 10000) const {
        cockpit::ControlInput still{};
        cockpit::ControlInput changed{};
        changed.throttle = 1.0f;
        changed.pitch = 0.7f;
        changed.roll = -0.6f;
        changed.rudder = 0.5f;
        changed.brake = 0.4f;
        changed.trigger = 0.9f;
        changed.head_x = 0.11f;
        changed.head_y = 0.22f;
        changed.head_z = -0.33f;
        changed.head_rot = cockpit::wire::normalized({0.1f, 0.2f, 0.3f, 0.9f});
        changed.left_x = -0.41f;
        changed.left_y = 0.42f;
        changed.left_z = -0.43f;
        changed.left_rot = cockpit::wire::normalized({0.3f, 0.1f, 0.2f, 0.8f});
        changed.right_x = 0.51f;
        changed.right_y = -0.52f;
        changed.right_z = 0.53f;
        changed.right_rot = cockpit::wire::normalized({0.2f, 0.3f, 0.1f, 0.85f});
        changed.grip_left = 0.6f;
        changed.grip_right = 0.7f;
        changed.buttons = 0xA5;
        // A WIDE KIND, so the worst case is the worst the wire can carry: 21 bits where 17 took 5 (lane/kinds).
        changed.kind_wanted = 300;
        changed.join_wanted = 9;
        // A WIDE SEAT, so the worst case is the worst the wire can carry (lane/seats, 2026-09-18).
        changed.join_seat = 300;
        changed.menu_request = 5;
        // A WIDE CHANNEL, so the worst case is the worst the wire can carry.
        changed.command_channel = 300;
        changed.command_value = 173;
        changed.command_seq = 255;
        changed.room_active = true;
        changed.room_id = 1;
        changed.room_endpoint = 377;
        changed.room_value = 211;
        changed.room_revision = 43123;
        changed.room_seq = 51119;

        const auto encode = [](const cockpit::ControlInput* previous,
                               const cockpit::ControlInput& current) {
            ashiato::BitBuffer bits;
            ashiato::ComponentSerializationContext context{};
            ashiato::sync::SyncComponentTraits<cockpit::ControlInput>::serialize(
                previous, current, bits, context);
            return bits;
        };
        const ashiato::BitBuffer full = encode(nullptr, still);
        const ashiato::BitBuffer unchanged = encode(&still, still);
        const ashiato::BitBuffer worst = encode(&still, changed);

        iterations = std::clamp<int64_t>(iterations, 1, 1000000);
        std::uint64_t sink = 0;
        const auto began = std::chrono::steady_clock::now();
        for (int64_t i = 0; i < iterations; ++i) {
            for (int frame = 0; frame < 8; ++frame) {
                const bool odd = ((i * 8 + frame) & 1) != 0;
                sink += encode(odd ? &still : &changed, odd ? changed : still).bit_size();
            }
        }
        const double elapsed_us = std::chrono::duration<double, std::micro>(
            std::chrono::steady_clock::now() - began).count();
        Dictionary out;
        out["full_bits"] = static_cast<int64_t>(full.bit_size());
        out["unchanged_delta_bits"] = static_cast<int64_t>(unchanged.bit_size());
        out["all_changed_delta_bits"] = static_cast<int64_t>(worst.bit_size());
        out["eight_frame_encode_us"] = elapsed_us / static_cast<double>(iterations);
        out["iterations"] = iterations;
        out["checksum"] = static_cast<int64_t>(sink);
        return out;
    }

    /// HOW MANY CHORES OF ONE KIND A TICK WILL PAY FOR, by the kind's name: `look_ahead`,
    /// `leg_check`, or a scripted one. An int is a COUNT, negative for no budget; a float in
    /// (0, 1] is a SHARE of the chores registered to the kind, ceil(registered x share) and never
    /// less than one. Past it only a chore that has waited its kind's `max_ticks` is served, and
    /// that one is counted as an overrun. Server only; see `ChoreRota`.
    bool set_chore_budget(const String& name, const Variant& budget) {
        const auto kind = chore_kind_named(name);
        std::uint32_t count = 0;
        std::uint32_t share_ppm = 0;
        if (kind == cockpit::ChoreRota::kNoKind || !read_budget(budget, count, share_ppm)) {
            return false;
        }
        return share_ppm > 0 ? rota_.set_share(kind, share_ppm) : rota_.set_budget(kind, count);
    }

    /// An int is a count (negative, none); a float in (0, 1] a share in millionths. Anything
    /// else, and a share outside that, is refused.
    static bool read_budget(const Variant& budget, std::uint32_t& count, std::uint32_t& share_ppm) {
        const std::uint32_t none = std::numeric_limits<std::uint32_t>::max();
        count = none;
        share_ppm = 0;
        if (budget.get_type() == Variant::INT) {
            const int64_t asked = budget;
            count = asked < 0 ? none : static_cast<std::uint32_t>(std::min<int64_t>(asked, none - 1));
            return true;
        }
        if (budget.get_type() == Variant::FLOAT) {
            const double share = budget;
            if (!(share > 0.0 && share <= 1.0)) {
                return false;
            }
            share_ppm = static_cast<std::uint32_t>(
                std::clamp<int64_t>(std::llround(share * 1000000.0), 1, 1000000));
            return true;
        }
        return false;
    }

    /// WHAT EVERY KIND ON THE ROTA HAS DONE since the session started or the report was reset:
    /// its settings, how many are on it and waiting, how many were served and how many of those
    /// over budget, the intervals between two serves of one chore (mean and worst, in ticks),
    /// how many a tick, and what the serving cost in microseconds a tick. The time is MEASURED
    /// and decides nothing. `digest` folds every serve's tick, kind and id, so two worlds that
    /// served the same chores on the same ticks print the same one.
    Dictionary chore_report() const {
        Dictionary kinds;
        for (std::size_t k = 0; k < rota_.kind_count(); ++k) {
            const auto kind = static_cast<cockpit::ChoreRota::Kind>(k);
            const cockpit::ChoreKind& book = rota_.kind(kind);
            const cockpit::ChoreStats& stats = rota_.stats(kind);
            Dictionary row;
            row["target_ticks"] = static_cast<int64_t>(book.target_ticks);
            row["max_ticks"] = static_cast<int64_t>(book.max_ticks);
            row["jitter_ticks"] = static_cast<int64_t>(book.jitter_ticks);
            row["urgent_ticks"] = static_cast<int64_t>(book.urgent_ticks);
            row["urgent_max_ticks"] = static_cast<int64_t>(book.urgent_max_ticks);
            row["scripted"] = k < chore_calls_.size() && chore_calls_[k].is_valid();
            // What this tick pays for, whichever way it was asked for; -1 for none.
            const std::uint32_t now_budget = rota_.budget_now(kind);
            row["budget"] = now_budget == std::numeric_limits<std::uint32_t>::max()
                ? static_cast<int64_t>(-1)
                : static_cast<int64_t>(now_budget);
            row["share"] = static_cast<double>(book.share_ppm) / 1000000.0;
            row["registered"] = static_cast<int64_t>(rota_.registered(kind));
            row["waiting"] = static_cast<int64_t>(rota_.waiting(kind));
            row["served"] = static_cast<int64_t>(stats.served);
            row["overruns"] = static_cast<int64_t>(stats.overruns);
            row["ticks"] = static_cast<int64_t>(stats.ticks);
            row["served_last_tick"] = static_cast<int64_t>(stats.served_last_tick);
            row["served_most_in_a_tick"] = static_cast<int64_t>(stats.served_most_in_a_tick);
            row["served_per_tick"] = stats.ticks > 0
                ? static_cast<double>(stats.served) / static_cast<double>(stats.ticks)
                : 0.0;
            row["intervals"] = static_cast<int64_t>(stats.intervals);
            row["mean_interval"] = stats.intervals > 0
                ? static_cast<double>(stats.interval_sum) / static_cast<double>(stats.intervals)
                : 0.0;
            row["worst_interval"] = static_cast<int64_t>(stats.worst_interval);
            const bool timed = k < chore_usec_sum_.size() && stats.ticks > 0;
            row["usec_per_tick"] =
                timed ? chore_usec_sum_[k] / static_cast<double>(stats.ticks) : 0.0;
            row["usec_worst_tick"] = k < chore_usec_worst_.size() ? chore_usec_worst_[k] : 0.0;
            kinds[String(book.name.c_str())] = row;
        }
        Dictionary out;
        out["kinds"] = kinds;
        out["frame"] = static_cast<int64_t>(served_frame_);
        out["digest"] = String::num_int64(static_cast<int64_t>(rota_.digest()), 16);
        return out;
    }

    /// Start the counts again, for a measurement over a window. Settings and chores stay.
    void reset_chore_report() {
        rota_.reset_stats();
        std::fill(chore_usec_sum_.begin(), chore_usec_sum_.end(), 0.0);
        std::fill(chore_usec_worst_.begin(), chore_usec_worst_.end(), 0.0);
    }

    /// A KIND OF CHORE A SCRIPT DOES: `callback(id, waited_ticks)` is called for each one served,
    /// on the same rules as the autopilots' own -- the same wheel, the same budget a tick, forced
    /// at the limit -- on the server, after the physics and outside the job, so a callback may
    /// spawn, retire, or change the rota itself. The jitter is a quarter of the target either
    /// way and an urgent chore comes due on a quarter of it, as for the built-in kinds.
    ///
    /// Refused on a client or before `start`, for a name already on the rota, a target of none, a
    /// limit shorter than the target or longer than `kLongestChoreTicks`, and a callback that
    /// cannot be called. WHAT A CALL COSTS is measured in `tests/rota.gd`; see agents.md.
    bool add_chore_kind(const String& name, int64_t target_ticks, int64_t max_ticks,
                        const Variant& budget, const Callable& callback) {
        if (!started_ || !is_server_) {
            UtilityFunctions::push_warning(
                "[CockpitWorld] add_chore_kind: the rota is the server's, and this world is not one");
            return false;
        }
        std::uint32_t count = 0;
        std::uint32_t share_ppm = 0;
        if (!callback.is_valid() || name.is_empty() || target_ticks < 1 || max_ticks < target_ticks
            || max_ticks > kLongestChoreTicks || !read_budget(budget, count, share_ppm)) {
            UtilityFunctions::push_warning("[CockpitWorld] add_chore_kind: refused '", name,
                                           "': target ", target_ticks, ", limit ", max_ticks,
                                           ", budget ", budget, ", callback valid ",
                                           callback.is_valid());
            return false;
        }
        const auto target = static_cast<std::uint32_t>(target_ticks);
        cockpit::ChoreKind kind;
        kind.name = std::string(name.utf8().get_data());
        kind.target_ticks = target;
        kind.max_ticks = static_cast<std::uint32_t>(max_ticks);
        kind.budget = count;
        kind.share_ppm = share_ppm;
        kind.jitter_ticks = target / 4u;
        kind.urgent_ticks = std::max(1u, target / 4u);
        const cockpit::ChoreRota::Kind added = add_kind_to_rota(kind);
        if (added == cockpit::ChoreRota::kNoKind) {
            UtilityFunctions::push_warning("[CockpitWorld] add_chore_kind: '", name,
                                           "' is already on the rota");
            return false;
        }
        chore_calls_.resize(rota_.kind_count());
        chore_calls_[added] = callback;
        return true;
    }

    /// Put `id` on the rota for a kind, scripted or built in. `stream` is what its jitter hashes
    /// from, and the id itself when negative: something that stays put when other things are
    /// added. An id that is an entity comes off the rota when the entity is retired.
    bool add_chore(const String& kind, int64_t id, int64_t stream) {
        const auto found = chore_kind_named(kind);
        return found != cockpit::ChoreRota::kNoKind
            && rota_.add(static_cast<std::uint64_t>(id), found,
                         static_cast<std::uint64_t>(stream < 0 ? id : stream), served_frame_);
    }

    bool remove_chore(const String& kind, int64_t id) {
        const auto found = chore_kind_named(kind);
        return found != cockpit::ChoreRota::kNoKind
            && rota_.remove(static_cast<std::uint64_t>(id), found);
    }

    /// A THREAT FLAGGED: while urgent a chore comes due on a quarter of its target and is forced
    /// at a quarter of its limit, so it is served sooner even when the rota is contended.
    bool set_chore_urgent(const String& kind, int64_t id, bool urgent) {
        const auto found = chore_kind_named(kind);
        return found != cockpit::ChoreRota::kNoKind
            && rota_.set_urgent(static_cast<std::uint64_t>(id), found, urgent, served_frame_);
    }

    Dictionary resim_stats() const {
        Dictionary out;
        out["count"] = resim_count_;
        out["last_span"] = last_resim_span_;
        out["ticks"] = resim_ticks_;
        out["worst_span"] = worst_resim_span_;
        out["last_from"] = last_resim_from_;
        out["last_to"] = last_resim_to_;
        return out;
    }

    // ---- the sync tracer -----------------------------------------------------------
    //
    // A build-time capability (ASHIATO_GD_WITH_TRACING) with a runtime switch. Asking for
    // it in a binary that does not have it says so rather than silently recording nothing.

    /// Must be called BEFORE start(): the tracer is attached as the client or server is
    /// built, and there is nowhere to hang it afterwards.
    bool set_tracing(bool on) {
#ifdef ASHIATO_GD_WITH_TRACING
        tracing_ = on;
        return true;
#else
        (void)on;
        tracing_ = false;
        return false;
#endif
    }

    bool tracing_available() const {
#ifdef ASHIATO_GD_WITH_TRACING
        return true;
#else
        return false;
#endif
    }

    /// Drain what the tracer has seen since the last call, oldest first.
    ///
    /// Drained rather than accumulated, and capped: a session generates thousands of
    /// events a second and a viewer wants the recent past, not a log that eats the
    /// process.
    Array take_trace_events() {
        Array out;
        for (auto& event : trace_events_) {
            out.push_back(event);
        }
        trace_events_.clear();
        return out;
    }

    int64_t trace_events_dropped() const {
        return trace_dropped_;
    }

    /// ONLY THE RECEIPTS, NOT THE EVENTS: with tracing on, every event still reaches `received_frames` and none is made
    /// into a Dictionary. For a joined machine in a real session, where a Dictionary per event -- about 700 a tick at a
    /// hundred craft -- would be most of what the process did. Before `start`, with `set_tracing`.
    void set_receipts_only(bool on) {
        receipts_only_ = on;
    }

    /// EVERY TRACE EVENT INTO A DIRECTORY, in ashiato-sync's own ktrace format, for upstream to read.
    ///
    /// `-- --sync-trace-dir=<path>`, see `Sim.start`. This is the raw capture ashiato-sync issue #17
    /// asked for: the library's own asynchronous writer, with packet logs on and frame data and
    /// serialization payloads off, which is the `TraceOptions` the maintainer specified.
    ///
    /// BEFORE start(), like `set_tracing`: the sink is attached as the client or server is built.
    ///
    /// The writer is chained IN FRONT OF the receipts callback rather than replacing it, because
    /// `set_tracer` and `set_trace_options` each reset the other (ashiato-sync
    /// `src/client/tracing.cpp:211-221`, `src/server.cpp:527-538`), and `priority_peers`' stalest-craft
    /// number is the receipts. Asking for both without the chain silently loses one of them.
    void set_sync_trace_dir(const String& directory) {
        sync_trace_dir_ = directory;
    }

    /// Flush and close the trace files, before the process goes away.
    ///
    /// The writer is asynchronous -- a thread per sink with a queue in front of it
    /// (ashiato-sync `src/tracing.cpp:516-534`) -- so a killed process loses its tail. The suite that
    /// captures for upstream asks for this and then waits for the child to leave of its own accord.
    void close_sync_trace() {
#ifdef ASHIATO_GD_WITH_TRACING
        if (trace_writer_ != nullptr) {
            trace_writer_->flush();
            trace_writer_->close();
        }
#endif
    }

    bool sync_trace_open() const {
#ifdef ASHIATO_GD_WITH_TRACING
        return trace_writer_ != nullptr;
#else
        return false;
#endif
    }

    /// WHEN EACH CRAFT'S STATE LAST ARRIVED: this machine's entity -> the server frame of the newest VehicleState record
    /// its client received, and `newest` -> the newest of them all. What a machine was SENT, which the server's own
    /// `component_sent` cannot say: sync traces that while it serialises, before it asks whether the record fits the
    /// budget. `count` is every VehicleState record received, for a rate. Empty unless tracing was on at `start`.
    Dictionary received_frames() const {
        Dictionary out;
        Dictionary frames;
        for (const auto& [entity, frame] : received_frames_) {
            frames[static_cast<int64_t>(entity)] = frame;
        }
        out["frames"] = frames;
        out["newest"] = newest_received_frame_;
        out["count"] = static_cast<int64_t>(received_count_);
        return out;
    }

